 *
 * @param {HTMLDocument} doc - The document of the message window.
 * @param {"ok"|"notok"} state - The state to test for.
 * @returns {boolean}
 */
hasEncryptedIconState(doc, state) {
  return !!doc.querySelector(
    `#encryptedHdrIcon[src*=message-encrypted-${state}]`
  );
},
